    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.saturation_mask = 0u;
    wo_output.slew_mask = 0u;
    return;
}
if ((wo_input.wheels == NULL) || (wo_input.count != 4u)) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.saturation_mask = 0u;
    wo_output.slew_mask = 0u;
    return;
}
if (!(wo_config.release_rad_s >= 0.0) ||
    !(wo_config.release_rad_s < wo_config.warn_rad_s) ||
    !(wo_config.warn_rad_s < wo_config.trip_rad_s) ||
    !isfinite(wo_config.release_rad_s) || !isfinite(wo_config.warn_rad_s) ||
    !isfinite(wo_config.trip_rad_s)) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.saturation_mask = 0u;
    wo_output.slew_mask = 0u;
    return;
}
if (!isfinite(wo_config.dt_s) || (wo_config.dt_s <= 0.0) ||
    !isfinite(wo_config.prediction_horizon_s) || (wo_config.prediction_horizon_s <= 0.0) ||
    !isfinite(wo_config.torque_limit) || (wo_config.torque_limit <= 0.0) ||
    !isfinite(wo_config.torque_slew) || (wo_config.torque_slew <= 0.0) ||
    !isfinite(wo_config.gain) || (wo_config.gain < 0.0)) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.saturation_mask = 0u;
    wo_output.slew_mask = 0u;
    return;
}
if ((wo_config.minimum_active_cycles < 1u) || (wo_config.minimum_active_cycles > 100u) ||
    (wo_config.release_cycles < 1u) || (wo_config.release_cycles > 100u) ||
    (wo_config.recovery_cycles < 1u) || (wo_config.recovery_cycles > 100u)) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.saturation_mask = 0u;
    wo_output.slew_mask = 0u;
    return;
}
for (i = 0u; i < 4u; i++) {
    if (!isfinite(wo_input.wheels[i].speed_rad_s) ||
        !isfinite(wo_input.wheels[i].inertia_kg_m2)) {
        wo_state.mode = WO_FAULT;
        wo_output.mode = WO_FAULT;
        wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
        wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
        wo_output.momentum_norm = 0.0;
        wo_output.saturation_mask = 0u;
        wo_output.slew_mask = 0u;
        return;
    }
}

if (wo_input.enable == 0) {
    wo_state.mode = WO_OFF;
    wo_state.history_initialized = 0;
    wo_state.clean = 0u;
    wo_state.elapsed = 0u;
    wo_state.recovery_count = 0u;
    wo_state.previous_torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.mode = WO_OFF;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0u;
    wo_output.saturation_mask = 0u;
    wo_output.slew_mask = 0u;
    for (i = 0u; i < 4u; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    return;
}

st = adcs_wheel_momentum(wo_input.wheels, wo_input.count, &momentum);
if (st != ADCS_OK) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.saturation_mask = 0u;
    wo_output.slew_mask = 0u;
    return;
}
if (!adcs_is_finite_vec3(&momentum)) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.saturation_mask = 0u;
    wo_output.slew_mask = 0u;
    return;
}

if (wo_state.history_initialized == 0) {
    for (i = 0u; i < 4u; i++)
        wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    wo_state.history_initialized = 1;
}

dt = wo_config.dt_s;
trip_mask = 0u;
for (i = 0u; i < 4u; i++) {
    a_val = (wo_input.wheels[i].speed_rad_s - wo_state.previous_speed_rad_s[i]) / dt;
    p_val = wo_input.wheels[i].speed_rad_s + a_val * wo_config.prediction_horizon_s;
    wo_output.acceleration_rad_s2[i] = a_val;
    wo_output.predicted_speed_rad_s[i] = p_val;
    wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    mag = fabs(wo_input.wheels[i].speed_rad_s);
    if (mag > max_speed) max_speed = mag;
    mag = fabs(p_val);
    if (mag > pred_max) pred_max = mag;
    if (mag >= wo_config.trip_rad_s) trip_mask |= (1u << i);
}
wo_output.maximum_speed = max_speed;
wo_output.predicted_maximum_speed = pred_max;
wo_output.predicted_trip_mask = trip_mask;
wo_output.momentum = momentum;
wo_output.momentum_norm = adcs_vec3_norm(&momentum);

cmd = (adcs_vec3_t){0.0, 0.0, 0.0};
switch (wo_state.mode) {
case WO_OFF:
    if (pred_max >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0u;
        wo_state.clean = 0u;
    } else if (pred_max >= wo_config.warn_rad_s) {
        wo_state.mode = WO_WATCH;
    }
    break;
case WO_WATCH:
    if (pred_max >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0u;
        wo_state.clean = 0u;
    } else if (pred_max < wo_config.warn_rad_s) {
        wo_state.mode = WO_OFF;
    }
    break;
case WO_ACTIVE:
    wo_state.elapsed++;
    cmd = adcs_vec3_scale(&momentum, -wo_config.gain);
    break;
case WO_RECOVERY:
    if (pred_max >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0u;
        wo_state.clean = 0u;
    } else {
        cmd = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
    break;
case WO_FAULT:
default:
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.momentum = momentum;
    wo_output.momentum_norm = adcs_vec3_norm(&momentum);
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.saturation_mask = 0u;
    wo_output.slew_mask = 0u;
    return;
}

{
    double pre_vals[3], post_vals[3], deltas[3];
    pre_vals[0] = ADCS_CLAMP(cmd.x, -wo_config.torque_limit, wo_config.torque_limit);
    pre_vals[1] = ADCS_CLAMP(cmd.y, -wo_config.torque_limit, wo_config.torque_limit);
    pre_vals[2] = ADCS_CLAMP(cmd.z, -wo_config.torque_limit, wo_config.torque_limit);
    if (pre_vals[0] != cmd.x) sat_mask |= 1u;
    if (pre_vals[1] != cmd.y) sat_mask |= 2u;
    if (pre_vals[2] != cmd.z) sat_mask |= 4u;
    deltas[0] = pre_vals[0] - wo_state.previous_torque.x;
    deltas[1] = pre_vals[1] - wo_state.previous_torque.y;
    deltas[2] = pre_vals[2] - wo_state.previous_torque.z;
    dv = wo_config.torque_slew * wo_config.dt_s;
    post_vals[0] = pre_vals[0]; post_vals[1] = pre_vals[1]; post_vals[2] = pre_vals[2];
    for (i = 0u; i < 3u; i++) {
        double prev;
        switch (i) {
            case 0: prev = wo_state.previous_torque.x; break;
            case 1: prev = wo_state.previous_torque.y; break;
            default: prev = wo_state.previous_torque.z; break;
        }
        if (deltas[i] > dv) { post_vals[i] = prev + dv; slew_mask |= (1u << i); }
        else if (deltas[i] < -dv) { post_vals[i] = prev - dv; slew_mask |= (1u << i); }
    }
    cmd = (adcs_vec3_t){post_vals[0], post_vals[1], post_vals[2]};
}

wo_output.torque = cmd;
wo_output.saturation_mask = sat_mask;
wo_output.slew_mask = slew_mask;
wo_state.previous_torque = cmd;

if (wo_state.mode == WO_ACTIVE) {
    if (wo_state.elapsed >= wo_config.minimum_active_cycles &&
        wo_output.maximum_speed <= wo_config.release_rad_s &&
        wo_output.predicted_maximum_speed <= wo_config.release_rad_s) {
        wo_state.clean++;
    } else {
        wo_state.clean = 0u;
    }
    if (wo_state.clean >= wo_config.release_cycles) {
        wo_state.mode = WO_RECOVERY;
        wo_state.clean = 0u;
        wo_state.recovery_count = 0u;
    }
}

if (wo_state.mode == WO_RECOVERY && trip_mask == 0u) {
    wo_state.recovery_count++;
    if (wo_state.recovery_count >= wo_config.recovery_cycles) {
        wo_state.mode = WO_OFF;
        wo_state.recovery_count = 0u;
    }
}

wo_output.mode = wo_state.mode;

