case WO_ACTIVE:
    wo_state.elapsed++;
    cmd = adcs_vec3_scale(&momentum, -wo_config.gain);
    break;
case WO_RECOVERY:
    if (pred_max >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0u;
        wo_state.clean = 0u;
    } else {
        cmd = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
    break;
case WO_FAULT:
default:
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.momentum = momentum;
    wo_output.momentum_norm = adcs_vec3_norm(&momentum);
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
