candidates.raw:
size_t i;
double ax[4], spd[4], pred[4], amax = 0.0, pmax = 0.0;
adcs_wheel_t w[4];
adcs_vec3_t h;
adcs_vec3_t cmd_torque;
adcs_actuator_limit_t lim;
int fault = 0;

wo_output.predicted_trip_mask = 0U;
wo_output.saturation_mask = 0U;
wo_output.slew_mask = 0U;
wo_output.torque = (adcs_vec3_t){0, 0, 0};
wo_output.momentum = (adcs_vec3_t){0, 0, 0};
wo_output.momentum_norm = 0.0;

if ((wo_input.wheels == NULL) || (wo_input.count != 4U))
    fault = 1;
if (wo_input.enable != 0 && wo_input.enable != 1)
    fault = 1;
if (fault == 0) {
    if ((!isfinite(wo_config.release_rad_s)) || (!isfinite(wo_config.warn_rad_s)) ||
        (!isfinite(wo_config.trip_rad_s)) || (wo_config.release_rad_s < 0.0) ||
        (wo_config.release_rad_s >= wo_config.warn_rad_s) ||
        (wo_config.warn_rad_s >= wo_config.trip_rad_s))
        fault = 1;
}
if (fault == 0) {
    if ((!isfinite(wo_config.dt_s)) || (wo_config.dt_s <= 0.0))
        fault = 1;
    if ((!isfinite(wo_config.prediction_horizon_s)) || (wo_config.prediction_horizon_s <= 0.0))
        fault = 1;
    if ((!isfinite(wo_config.torque_limit)) || (wo_config.torque_limit <= 0.0))
        fault = 1;
    if ((!isfinite(wo_config.torque_slew)) || (wo_config.torque_slew <= 0.0))
        fault = 1;
    if ((!isfinite(wo_config.gain)) || (wo_config.gain < 0.0))
        fault = 1;
}
if (fault == 0) {
    if ((wo_config.minimum_active_cycles < 1U) || (wo_config.minimum_active_cycles > 100U) ||
        (wo_config.release_cycles < 1U) || (wo_config.release_cycles > 100U) ||
        (wo_config.recovery_cycles < 1U) || (wo_config.recovery_cycles > 100U))
        fault = 1;
}
if (fault == 0) {
    for (i = 0; i < 4U; i++)
        w[i] = wo_input.wheels[i];
    if (adcs_wheel_momentum(w, 4U, &h) != ADCS_OK)
        fault = 1;
    else if (!adcs_is_finite_vec3(&h))
        fault = 1;
}

if (fault != 0) {
    wo_state.mode = WO_FAULT;
    wo_state.history_initialized = 0;
    wo_state.clean = 0U;
    wo_state.elapsed = 0U;
    wo_state.recovery_count = 0U;
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
    wo_output.mode = WO_FAULT;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm = 0.0;
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    wo_output.recovery_count = 0U;
    return;
}

for (i = 0; i < 4U; i++)
    spd[i] = w[i].speed_rad_s;

if (!wo_state.history_initialized) {
    for (i = 0; i < 4U; i++) {
        wo_state.previous_speed_rad_s[i] = spd[i];
        ax[i] = 0.0;
    }
    wo_state.history_initialized = 1;
} else {
    for (i = 0; i < 4U; i++)
        ax[i] = (spd[i] - wo_state.previous_speed_rad_s[i]) / wo_config.dt_s;
}
for (i = 0; i < 4U; i++) {
    wo_state.previous_speed_rad_s[i] = spd[i];
    pred[i] = spd[i] + ax[i] * wo_config.prediction_horizon_s;
    wo_output.acceleration_rad_s2[i] = ax[i];
    wo_output.predicted_speed_rad_s[i] = pred[i];
    if (fabs(spd[i]) > amax)
        amax = fabs(spd[i]);
