        wo_output.predicted_trip_mask |= (unint32)(1U << i);
}
wo_output.maximum_speed = amax;
wo_output.predicted_maximum_speed = pmax;
wo_output.momentum = h;
wo_output.momentum_norm = adcs_vec3_norm(&h);

switch (wo_state.mode) {
case WO_OFF:
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    if (pmax >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.clean = 0U;
    } else if (pmax >= wo_config.warn_rad_s) {
        wo_state.mode = WO_WATCH;
    }
    break;
case WO_WATCH:
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    if (pmax >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.clean = 0U;
    } else if (pmax < wo_config.warn_rad_s) {
        wo_state.mode = WO_OFF;
    }
    break;
case WO_ACTIVE:
    cmd_torque = adcs_vec3_scale(&h, -wo_config.gain);
    {
        double v[3];
        v[0] = cmd_torque.x;
        v[1] = cmd_torque.y;
        v[2] = cmd_torque.z;
        for (i = 0; i < 3U; i++) {
            if (!isfinite(v[i])) {
                fault = 1;
                v[i] = 0.0;
            } else if (v[i] > wo_config.torque_limit) {
                v[i] = wo_config.torque_limit;
                wo_output.saturation_mask |= (unint32)(1U << i);
            } else if (v[i] < -wo_config.torque_limit) {
                v[i] = -wo_config.torque_limit;
                wo_output.saturation_mask |= (unint32)(1U << i);
            }
        }
        cmd_torque = (adcs_vec3_t){v[0], v[1], v[2]};
    }
    {
        double v[3], pt[3];
        pt[0] = wo_state.previous_torque.x;
        pt[1] = wo_state.previous_torque.y;
        pt[2] = wo_state.previous_torque.z;
        v[0] = cmd_torque.x;
        v[1] = cmd_torque.y;
        v[2] = cmd_torque.z;
        for (i = 0; i < 3U; i++) {
            double dv = v[i] - pt[i];
            if (dv > wo_config.torque_slew) {
                v[i] = pt[i] + wo_config.torque_slew;
                wo_output.slew_mask |= (unint32)(1U << i);
            } else if (dv < -wo_config.torque_slew) {
                v[i] = pt[i] - wo_config.torque_slew;
                wo_output.slew_mask |= (unint32)(1U << i);
            }
        }
        cmd_torque = (adcs_vec3_t){v[0], v[1], v[2]};
    }
    wo_output.torque = cmd_torque;
    wo_state.previous_torque = cmd_torque;
    wo_state.elapsed++;
    if (wo_state.elapsed >= wo_config.minimum_active_cycles) {
        if ((amax <= wo_config.release_rad_s) && (pmax <= wo_config.release_rad_s))
            wo_state.clean++;
        else
            wo_state.clean = 0U;
        if (wo_state.clean >= wo_config.release_cycles) {
            wo_state.mode = WO_RECOVERY;
            wo_state.clean = 0U;
            wo_state.recovery_count = 0U;
        }
    }
    break;
case WO_RECOVERY:
    cmd_torque = (adcs_vec3_t){0, 0, 0};
    {
        double v[3], pt[3];
        pt[0] = wo_state.previous_torque.x;
        pt[1] = wo_state.previous_torque.y;
        pt[2] = wo_state.previous_torque.z;
        v[0] = cmd_torque.x;
        v[1] = cmd_torque.y;
        v[2] = cmd_torque.z;
        for (i = 0; i < 3U; i++) {
            double dv = v[i] - pt[i];
            if (dv > wo_config.torque_slew) {
                v[i] = pt[i] + wo_config.torque_slew;
                wo_output.slew_mask |= (unint32)(1U << i);
            } else if (dv < -wo_config.torque_slew) {
                v[i] = pt[i] - wo_config.torque_slew;
                wo_output.slew_mask |= (unint32)(1U << i);
            }
        }
        cmd_torque = (adcs_vec3_t){v[0], v[1], v[2]};
    }
    wo_output.torque = cmd_torque;
    wo_state.previous_torque = cmd_torque;
    if (pmax >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.clean = 0U;
    } else {
        wo_state.recovery_count++;
        if (wo_state.recovery_count >= wo_config.recovery_cycles) {
            wo_state.mode = WO_OFF;
            wo_state.recovery_count = 0U;
        }
    }
    break;
default:
    wo_state.mode = WO_FAULT;
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
    break;
}
(void)lim;
if (fault != 0) {
    wo_state.mode = WO_FAULT;
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
}
wo_output.mode = wo_state.mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;
wo_output.recovery_count = wo_state.recovery_count;

