    if (limited.z - wo_state.previous_torque.z > msl) { limited.z = wo_state.previous_torque.z + msl; slewdmask |= 4U; }
    else if (wo_state.previous_torque.z - limited.z > msl) { limited.z = wo_state.previous_torque.z - msl; slewdmask |= 4U; }
