} else {
    wo_state.previous_torque = (adcs_vec3_t){0, 0, 0};
}

/* ACTIVE 释放证据 */
if (wo_state.mode == WO_ACTIVE) {
    if (wo_state.elapsed >= wo_config.minimum_active_cycles) {
        if (absmax_cur <= wo_config.release_rad_s && absmax_pred <= wo_config.release_rad_s) {
            wo_state.clean += 1U;
        } else {
            wo_state.clean = 0U;
        }
