}
wo_output.predicted_trip_mask = 0U;
for (i = 0; i < 4U; i++) {
    if (fabs(pred[i]) >= wo_config.trip_rad_s)
        wo_output.predicted_trip_mask |= (uint32_t)(1U << i);
}
wo_output.saturation_mask = satmask;
wo_output.slew_mask = slewdmask;
if (wo_state.mode == WO_ACTIVE || wo_state.mode == WO_RECOVERY) {
    wo_output.torque = wo_state.previous_torque;
} else {
    wo_output.torque = (adcs_vec3_t){0, 0, 0};
}

candidates.misra:
size_t i;
adcs_vec3_t axes[4];
int valid = 1;
double absmax_cur = 0.0, absmax_pred = 0.0;
int cur_has = 0, pred_has = 0;
int any_pred_trip = 0, any_pred_warn = 0;
double accel[4], pred[4], cur[4];
adcs_vec3_t momentum, cmd, limited;
uint32_t satmask = 0, slewdmask = 0;
double msl;

/* latch FAULT：只有 disable 或有效配置才会离开 */
if (wo_state.mode == WO_FAULT) {
